    'sound_packs.help_title' => 'Asterisk ses paketleri',
    'sound_packs.help_body' => 'Asterisk\'in resmî sistem seslerini ve bekleme müziklerini <code>downloads.asterisk.org</code> adresinden indirip kurar. Her paket tek bir dil ve formattır; Asterisk görüşmenin codec\'ine uyan formatı çalar, olmayanı dönüştürür (G.722 için g722, operatörler için ulaw/alaw önerilir).<br>- <strong>Temel (core):</strong> sistem anonsları, rakamlar, sesli posta. <strong>Ek (extra):</strong> ek anonslar; önce aynı dilin temel paketi kurulmalıdır.<br>- <strong>Bekleme müziği (opsound):</strong> <code>/var/lib/asterisk/moh/opsound</code> klasörüne kurulur; çalmak için Bekleme Müzikleri sekmesinde <strong>opsound</strong> adında bir MOH sınıfı oluşturun.<br>- <strong>Türkçe (AiPBX):</strong> AiPBX\'in kendi Türkçe sesleri (GitHub sürümü, SHA256 doğrulamalı); varsayılan dil Türkçe olduğundan kaldırırsanız sistem anonsları susar. Kaldırma yalnızca paketin kurduğu dosyaları siler.',
