    'backup.help_title' => 'Bir yedekte neler bulunur?',
    'backup.help_body' => 'Veritabanı ve yapılandırma: ayarlar, sertifikalar, yüklenen sesler ve bekleme müziği, eklentiler ve saklanan gizli anahtarları çözen anahtar. Çağrı kayıtları ve fakslar dahil değildir. Her gece bir yedek alınır ve eski olanlar aşağıda belirlenen gün sayısından sonra silinir.<br><br><strong>İndirilen yedekleri güvenli tutun:</strong> bu sistemin tüm şifrelerini ve gizli anahtarlarını içerirler.<br><br><strong>Geri yükleme, mevcut verileri yedekteki verilerle değiştirir</strong> ve o andan sonraki her şey kaybolur. Servisler yeniden başlar ve devam eden çağrılar sonlandırılır. Önce mevcut durumun bir yedeği alınır ve geri yükleme başarısız olursa bu yedek geri yüklenir.',
