    'system_update.page_title' => 'Sistem Güncelleme',
    'system_update.help_title' => 'Güncelleme nasıl çalışır?',
    'system_update.help_body' => 'Güncelleme önce veritabanının, ayarların ve Asterisk yapılandırmasının yedeğini alır, sonra yeni sürümü kurar ve her şeyin çalıştığını test eder. Bir sorun çıkarsa otomatik olarak önceki sürüme döner. Asterisk yalnızca güncelleme gerektirdiğinde (yeni bir Asterisk yapılandırması veya paketi) yeniden başlatılır; sayfa bunu aşağıda belirtir. Böyle bir güncelleme için süren görüşmelere ne olacağını seçersiniz: bitmelerini bekle veya sonlandır. Bekleme sırasında bunları yine de sonlandırabilir veya güncellemeyi iptal edebilirsiniz. Beklemenin ardından, güncellemenin kendisi sırasında başlayan bir görüşme de düşer. Diğer güncellemeler yalnızca Asterisk\'i yeniden yükler ve görüşmeler devam eder. Kurulum klasörü altında elle değiştirilen dosyalar güncellemeyi durdurmaz: yeni sürüm aynı dosyayı değiştirmediği sürece yedeğe kaydedilir ve korunur. Değiştirirse yeni sürüm kullanılır ve sayfa günlüğü dosyanın adını belirtir. Sunucuda da çalıştırılabilir: <code>sudo aipbx-update</code>',
