    'certificates.help_body' => 'Portal (HTTPS), WebRTC TURNS ve SIP-TLS/WSS aynı sertifikayı kullanır; burada yapılan değişiklik Apache, coturn ve Asterisk\'e birlikte uygulanır. <b>Let\'s Encrypt</b> ücretsizdir ve kendini otomatik yeniler; alan adının bu sunucuyu göstermesi ve 80 portunun internetten erişilebilir olması gerekir. Kurumunuzun sertifikası varsa <b>yükleyebilirsiniz</b> (PEM veya PFX); yüklenen sertifikalar otomatik yenilenmez, süresi dolmadan yenisini yükleyin. <b>Kendinden imzalı</b> sertifikada tarayıcı uyarı verir ve TURNS tarayıcılarda çalışmaz: güvenlik duvarı arkasındaki WebRTC aramalarında ses gelmeyebilir.',
