    'ai_models.help_body' => 'AI modellerini santralin kendisinde çalıştırır: metin ve ses sunucudan çıkmaz, API anahtarı ve ücret yoktur. Önce <strong>yerel AI çalışma ortamını</strong> kurun (yaklaşık 160 MB disk, bir kez indirilir), sonra ihtiyacınız olan modelleri lisanslarını onaylayarak indirin. Yüklü bir model bellek ve işlemci kullanır; hız testi bu sunucuda yeterince hızlı olup olmadığını gösterir. Görüşmeler önceliklidir: servis düşük işlemci önceliğiyle ve bellek sınırıyla çalışır. Ayrıntılar: docs/local-ai.md.',
