    'ai_tts.help_body' => 'Yazdığınız metni bulut seslendirme servisleriyle (Google, Amazon Polly, Azure, ElevenLabs, OpenAI) doğal bir sese çevirir. Sonucu dinleyebilir, MP3 olarak indirebilir veya tek tıkla <b>anons</b> olarak kaydedebilirsiniz: ses Asterisk\'in formatına (8 kHz WAV) çevrilip Sesler &amp; Anonslar\'a eklenir; IVR, gelen rota ve zaman koşullarında kullanılabilir (değişiklik Uygula ile etkinleşir). <b>Bu servisler ücretlidir</b> ve karakter başına faturalandırır; her seslendirme geçmişte karakter sayısıyla tutulur. Erişim anahtarları sağlayıcıların kendi konsollarından alınır, şifrelenerek saklanır ve sayfada bir daha gösterilmez.',
