    'phones.region_sip443_help' => 'TLS çıkışına yalnızca 443 üzerinden izin veren ağlar için. Bu telefonlar TLS ve 443 portunu alır. Bölgeye kendine ait bir SIP sunucu adı verin (örneğin DNS\'te bu sunucuyu işaret eden sip1.example.com): bu ada sahip bağlantılar santrale gider, 443 üzerindeki diğer her şey olduğu gibi kalır. Tekrar talep edildiğinde Let\'s Encrypt bu adı sertifikaya ekler. Aramaların ses trafiğinin (UDP) geçebilmesi gerekir. Santral bu telefonları 127.0.0.1 olarak görür, bu nedenle fail2ban onları engellemez.',
