    'storage.help_title' => 'Sohbet dosyaları nerede tutulur',
    'storage.help_body' => '<p>Sohbet ekleri, küçük resimleri ve grup resimleri varsayılan olarak sunucunun diskinde tutulur (<code>/var/lib/aipbx/chat_files</code>). S3 uyumlu bir depolama (AWS S3, MinIO, Wasabi, Backblaze B2, Cloudflare R2 …) seçilirse bir bucket\'a yazılır ve büyük dosyalar PBX\'te yer kaplamaz.</p><p>İndirmeler yine sohbet servisi üzerinden yapılır; bir sohbetin dosyalarını yalnızca katılımcıları açabilir, bucket gizli kalabilir. Geçişten önce kaydedilen dosyalar taşınana kadar diskten sunulur. Bucket ayarları kaydedilmeden önce denenir.</p><p>Arama kayıtları, sesli mesajlar ve fakslar yerel diskte kalır.</p>',
