    'vpn.err_unavailable' => 'VPN yardımcısı yanıt vermedi. Bu sayfanın gösterdiği gerçek durum olmayabilir; yanıt verene kadar hiçbir şeyi değiştirmeyin.',
    'fax.err_did_digits' => 'Numara yalnızca rakam içerebilir, başında isteğe bağlı bir + olabilir.',
    'health.desc_vpn' => 'Açıksa: VPN sunucusu çalışıyor ve VPN bağlantıları etkin',
    'vpn.server_title' => 'VPN Sunucusu',
    'vpn.client_title' => 'VPN İstemcisi',
    'vpn.server_help' => 'Ağınızın dışındaki telefonların, softphone\'ların ve dizüstü bilgisayarların bu santrale özel bir tünel üzerinden ulaşmasını sağlar. <strong>WireGuard</strong> (hızlı ve basit, önerilen) veya <strong>OpenVPN</strong> (bir cihaz gerektirdiğinde ya da güvenlik duvarından yalnızca TCP geçtiğinde) seçeneğini belirleyin. Bir cihaz ekleyin, ardından profilini o cihaza yükleyin; her cihazın kendi anahtarları vardır ve silindiğinde erişimi derhal kesilir. Telefonları Cihazlar altında gösterilen sunucunun VPN adresine kaydedin.<br><br><strong>Bir VPN cihazının erişebileceği yerler:</strong> Yalnızca bu santral: portal, SIP, çağrı sesi ve faks. Diğer cihazlara veya bu sunucunun arkasındaki ağlara erişemez, çünkü sunucu ağlar arasında yönlendirme yapmaz. SSH ile FTP ve TFTP servisleri bu cihazlara açık değildir. Başka bir VPN türüne geçmek cihazlara yeni profiller verir; eski türün cihazları saklanır ve geri döndüğünüzde tekrar çalışır. Portu veya genel adresi değiştirmek de profillerin yeniden yüklenmesini gerektirir.',
    'vpn.client_help' => 'Bu santrali başka bir ağa bağlar; örneğin yalnızca bir VPN üzerinden erişilebilen bir SIP dış hattına veya başka bir santrale. Sağlayıcınızın verdiği profili yükleyin (WireGuard <code>.conf</code> veya OpenVPN <code>.ovpn</code>) ve tünelin arkasındaki ağları listeleyin.<br><br><strong>Yalnızca listelediğiniz ağlar tüneli kullanır.</strong> Tüm trafiği VPN\'e yönlendiren bir profil kabul edilir, ancak santral hiçbir zaman her şeyi onun üzerinden yönlendirmez: çağrılar, dış hatlar ve bu sunucuya erişim de oraya taşınır ve kesilebilir. Bu sunucunun zaten kullandığı bir ağ listelenemez. Bir profildeki DNS ayarları yok sayılır.<br><br><strong>Yalnızca güvenli ayarlar kabul edilir.</strong> Bu dosyalar sunucuda komut çalıştırabilir (<code>PostUp</code>, <code>up</code>, <code>plugin</code> ve diğerleri); bu nedenle böyle bir satır içeren profil reddedilir ve sertifikalar yol olarak belirtilmek yerine OpenVPN dosyasının içinde yer almalıdır. Bir profildeki IPv6 adresleri kullanılmaz.',
