    'netsvc.help_body' => 'DHCP sunucusu provizyon sunucusunun adresini verirse (seçenek 66) masaüstü telefonlar onu kendileri bulur. DHCP ve TFTP ayrı ayrı açılıp kapatılır. <strong>DHCP sunucusu</strong> kapalıyken kendi DHCP sunucunuz kalır: aşağıdaki seçenekleri orada ayarlayın. Açıkken AiPBX bir arayüzde veya VLAN\'da adres dağıtır. <strong>TFTP sunucusu</strong> yüklediğiniz açılış dosyalarını ve yazılımları verir. Telefona özel yapılandırma (SIP şifresiyle) her zaman HTTPS üzerinden verilir, asla TFTP ile değil.',
