    'netsvc.dhcp_options_help' => 'Her satıra bir tane: <code>kod,değer</code>, ör. <code>66,ftp://192.168.10.2/</code>. Baytlar iki nokta ile onaltılık yazılır (<code>43,0a:04:c0:a8:0a:02</code>), diğer değerler metin veya IP adresi olarak. Aynı kod, AiPBX\'in verdiği değerin yerine geçer (66, 160, 150, 42, 3, 6); ek seçenekler telefon istemese de gönderilir. Tırnak, # ve ters bölü kullanılamaz.',
