    'health.header_title' => 'Sağlık kontrolü',
    'health.help_title' => 'Sağlık kontrolü nasıl çalışır',
    'health.help_body' => '<p>Sunucu kendini arka planda kontrol eder (her dakika vakti gelen kontrolleri çalıştırır), bir şey çalışmaz olduğunda ve tekrar çalıştığında seçilen kişilere e-posta gönderir. Her kontrolün kendi sıklığı vardır; <strong>Kapalı</strong> kontrolü kapatır.</p><p>Kısa bir aksaklık için alarm gitmesin diye 15 dakikada bir veya daha sık çalışan kontroller sorunu ancak arka arkaya iki kötü sonuçtan sonra bildirir. Sorun sürdükçe alarm seçilen saat sonra tekrarlanır. <strong>Şimdi kontrol et</strong> tüm kontrolleri bir dakika içinde çalıştırır.</p><p><strong>Günlük özet</strong> aynı kişilere gider: dünkü çağrılar ve fakslar, tüm kontrollerin durumu. Komut satırı: <code>sudo aipbx-selftest</code>. Bkz. docs/health.md.</p><p>Sunucu tamamen kapanırsa kendisi e-posta gönderemez; bunun için dışarıdan izleyin.</p>',
