    'health.alarms_title' => 'Alarm e-postaları',
    'health.alarms_help' => 'Bir kontrol hata ya da uyarı verdiğinde ve tekrar çalıştığında kime e-posta gideceği. Günlük özet de aynı kişilere gider.',
