    'call_quality.title' => 'Çağrı kalitesi',
    'call_quality.header_title' => 'Çağrı kalitesi (RTCP)',
    'call_quality.help_title' => 'Nasıl ölçülür',
    'call_quality.help_body' => '<p>Her çağrı bacağı kendi ses kalitesini RTCP ile bildirir. Sinyalleşme yakalama etkinken (PBX ayarları → Sinyalleşme), AiPBX bu raporları her dakika okur: çağrı bacağı, trunk ve dahili hat başına paket kaybı ve jitter. PBX üzerinde hiçbir şey değiştirilmez.</p><p><strong>Gelen</strong> bu PBX\'in aldığı, <strong>giden</strong> karşı tarafın aldığı trafiktir. <em>Gelen</em> yönde ses kaybeden bir trunk operatör tarafına, <em>giden</em> yönde bizim tarafımıza (uplink, güvenlik duvarı, bant genişliği) işaret eder; <em>giden</em> yönde ses kaybeden bir dahili hat ise genellikle zayıf Wi-Fi bağlantısındaki bir telefondur.</p><p>Bir bacak, bir yöndeki iki raporu aşağıda belirlenen kayba ulaştığında <strong>kötü</strong>, %s %% değerinden itibaren <strong>orta</strong> kabul edilir. Jitter, RTP zaman damgası birimindedir (G.711 için 8 = 1 ms). Ses kaybeden bir trunk veya dahili hat, "Çağrı kalitesi" sistem durumu denetiminde bir sorundur: uyarı zilinde görünür ve diğer alarmlar gibi e-posta ile bildirilir.</p>',
    'call_quality.capture_off' => 'Sinyalleşme yakalama kapalı, bu nedenle hiçbir şey ölçülmüyor.',
    'call_quality.capture_off_link' => 'PBX ayarları → Sinyalleşme altından etkinleştirin',
    'call_quality.no_reports' => 'Son 24 saatte RTCP raporu yok. Bir çağrı yapın; ilk ölçümler çağrıdan bir dakika sonra görünür.',
