    'firewall.help_common' => 'Genel sekmesi her ağ kartının kullandığı kuralları içerir: buraya eklediğiniz, kaldırdığınız veya kapattığınız her şey tüm kartlar için geçerlidir. VPN gibi kendi kuralları olan sanal arayüzler genel kuralları almaz; sekmeleri açtıkları her şeyi listeler ve kurallarını oraya girersiniz. Bir kartın kendi sekmesi yalnızca onda farklı olanı gösterir: yalnızca o karta özel kurallar ve onda kapatılan genel kurallar. Genel sekmesinde kart butonları bir kuralı tek bir kartta kapatır veya açar. Bir kuralı silmeden denemek için kapatın; açtığınızda önceki haliyle geri gelir. Bir kaynak belirtildiğinde, portu yalnızca o adres veya ağ kullanabilir. Bağlantınızı, aramaları veya telefonları kesebilecek bir değişiklikten önce sayfa size ne yapacağını bildirir.',
